def character_sprite(name: str) -> Image.Image:
    w,h,encoded = DATA[name]
    payload=zlib.decompress(base64.urlsafe_b64decode(encoded))
    binary=Image.frombytes("1",(w,h),payload)
    alpha=binary.convert("L")
    sprite=Image.new("RGBA",(w,h),(28,40,54,0))
    sprite.putalpha(alpha)
    return sprite
